import subprocess
import os
import shutil
from glob import glob

def task_func(src_folder, dst_folder):
    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder)

    all_items = glob(os.path.join(src_folder, '*'))
    files = [f for f in all_items if os.path.isfile(f)]

    failed_files = []
    processes = []

    for f in files:
        try:
            p = subprocess.Popen(['gzip', f])
            processes.append((p, f))
        except Exception:
            failed_files.append(os.path.basename(f))

    for p, f in processes:
        p.wait()
        gz_file = f + '.gz'
        if p.returncode == 0 and os.path.exists(gz_file):
            try:
                shutil.move(gz_file, os.path.join(dst_folder, os.path.basename(gz_file)))
            except Exception:
                failed_files.append(os.path.basename(f))
        else:
            if os.path.basename(f) not in failed_files:
                failed_files.append(os.path.basename(f))

    success = len(failed_files) == 0
    message = "All files compressed and moved successfully." if success else "Some files failed to compress or move."

    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

